    if (message == null || message.isEmpty()) {
        throw new IllegalArgumentException("Message cannot be null or empty");
    }

    // Assuming a hashmap to keep track of the last printed timestamp for each message
    Map<String, Integer> lastPrintedTimestamps = new HashMap<>();
    if (!lastPrintedTimestamps.containsKey(message)) {
        lastPrintedTimestamps.put(message, timestamp);
        return true;
    } else {
        int lastTimestamp = lastPrintedTimestamps.get(message);
        if (timestamp - lastTimestamp >= 10) {
            lastPrintedTimestamps.put(message, timestamp);
            return true;
        }
    }

    return false;
}

