private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null || dir == -1) {
        throw new IllegalArgumentException("Invalid inputs");
    }

    // Initialize the current node and the result circulator
    Node currentNode = start;
    OuterFaceCirculator resultCirculator = null;

    // Traverse outer face in the specified direction
    while (!currentNode.equals(stop)) {
        if (predicate.test(currentNode)) {
            resultCirculator = new OuterFaceCirculator(currentNode);
            break;
        }

        // Move to the next node in the direction of traversal
        switch (dir) {
            case 0: currentNode = currentNode.next(); break;
            case 1: currentNode = currentNode.prev(); break;
            case 2: currentNode = currentNode.right(); break;
            case 3: currentNode = currentNode.left(); break;
        }
    }

    return resultCirculator;
}

