private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.size() <= 1) {
        return true; // A set of 1 or less vertices is trivially a clique
    }

    // Determine if all vertices are adjacent to each other
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false; // Find a vertex with no adjacent vertex
            }
        }
    }

    return true; // All vertices were found to be adjacent to each other
}

